import { readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import {
  conversationSynthesis,
  type ConversationSynthesisInput,
} from "../src/prompts/index.js";

// Generated by the data plane's Python builder
// (introspection-cloud apps/dataplane-api/tests/test_synthesis_parity_fixtures.py) and copied here.
const FIXTURES = join(
  dirname(fileURLToPath(import.meta.url)),
  "fixtures",
  "conversation-synthesis",
);

interface Fixture {
  name: string;
  input: ConversationSynthesisInput;
  expected: { prompt?: string; plan?: unknown; outcome?: unknown };
}

/** Keep `timestamp_ns` exact: it is past what a JSON number holds. */
function load(file: string): Fixture {
  return JSON.parse(
    readFileSync(join(FIXTURES, file), "utf8"),
    (key, value, context?: { source?: string }) =>
      key === "timestamp_ns" && context?.source !== undefined
        ? context.source
        : value,
  ) as Fixture;
}

describe("conversation_synthesis@1 matches the Python builder", () => {
  for (const file of readdirSync(FIXTURES).filter((name) =>
    name.endsWith(".json"),
  )) {
    const fixture = load(file);
    it(fixture.name, () => {
      const built = conversationSynthesis.build(
        fixture.input,
        Number.MAX_SAFE_INTEGER,
      );
      if (fixture.expected.prompt !== undefined) {
        expect(built.prompt).toBe(fixture.expected.prompt);
        expect(built.state).toEqual({ plan: fixture.expected.plan });
      } else {
        expect(built.state).toEqual({ outcome: fixture.expected.outcome });
      }
    });
  }
});
